import heapq
from typing import Optional


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}  # customer_name -> is_vip
        self._tickets: dict[int, dict] = {}
        self._ticket_counter: int = 0
        self._order_counter: int = 0  # Tie-breaker to maintain FIFO order
        self._queue: list[tuple[int, int, int, int]] = []  # Heap queue

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")

        self._ticket_counter += 1
        ticket_id = self._ticket_counter

        is_vip = self._customers.get(customer, False)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "queued",  # Possible values: "queued", "in_progress", "closed"
        }

        self._push_to_queue(ticket_id, is_vip, priority)
        return ticket_id

    def next_ticket(self) -> Optional[int]:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        while self._queue:
            _, _, _, ticket_id = heapq.heappop(self._queue)
            ticket_info = self._tickets.get(ticket_id)
            if ticket_info and ticket_info["status"] == "queued":
                ticket_info["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket_info = self._tickets[ticket_id]
        if ticket_info["status"] == "closed":
            raise ValueError(f"Ticket {ticket_id} is closed and cannot be reopened.")

        if ticket_info["status"] != "queued":
            ticket_info["status"] = "queued"
            is_vip = self._customers.get(ticket_info["customer"], False)
            self._push_to_queue(ticket_id, is_vip, ticket_info["priority"])

    def _push_to_queue(self, ticket_id: int, is_vip: bool, priority: str) -> None:
        # Smaller tuple values take precedence in Python's min-heap.
        # VIP: 0 for VIP, 1 for non-VIP
        vip_rank = 0 if is_vip else 1
        # Priority: critical (0) > high (1) > normal (2)
        priority_rank = -(self.PRIORITIES.index(priority))
        self._order_counter += 1
        heapq.heappush(
            self._queue, (vip_rank, priority_rank, self._order_counter, ticket_id)
        )
